Section Call.
Variables (fx0 : FPState) (R0 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (cr1 : credit).
Variables (sp1 ra v : Z) (lvX : list PQM.alvl) (bX kX : Z) (kx : PM.vstr) (kgx : Z) (kbx : PM.vstr) (gx : Z).
Let stK (ky : PM.vstr) (kgy : Z) : PQM.ast := PQM.AST lvX bX kX ky kgy kbx gx.
Hypothesis Y1 : S - 3776 <= sp1.
Hypothesis Y2 : sp1 <= S.
Hypothesis Y3 : sp1 mod 16 = 0.
Hypothesis X1 : getr R0 (reg 1) = Z_to_bv 64 ra.
Hypothesis RA : L5.ra_ok ra.
Hypothesis X2 : getr R0 (reg 2) = Z_to_bv 64 sp1.
Hypothesis X3 : getr R0 (reg 3) = Z_to_bv 64 (pa_gp AD).
Hypothesis X4 : getr R0 (reg 4) = Z_to_bv 64 (pa_tp AD).
Hypothesis X10 : getr R0 (reg 10) = Z_to_bv 64 v.
Hypothesis Hv : 0 <= v < 2 ^ 64.
Hypothesis X11 : getr R0 (reg 11) = Z_to_bv 64 (oa + 24).
Hypothesis CM1 : cm M1.
Hypothesis W1 : world M1.
Hypothesis AA1 : adaptor_at M1 oa ov (stK kx kgx).
Variable bs0 : list Z.
Hypothesis KC1 : kcontent M1 (oa + 24) kx bs0.
Hypothesis KOK : PQM.ks_ok PQM.SMK kx kgx.
Hypothesis KOB : PQM.ks_ok PQM.SMB kbx gx.
Hypothesis ROOM : PM.vs_size kx + 20 <= PQM.SMK.
Hypothesis CL : PMSP.credit_le (PQM.pot_adaptor L (stK kx kgx)) cr1.
Hypothesis MOK1 : PMSP.model_ok model1.
Hypothesis HH1 : hi_heap HI (PQM.aown (stK kx kgx) ++ LBX) cr1 M1 (m_vmmaps model1).
Hypothesis CONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (kx' : PM.vstr) (kgx' : Z) (cr' : credit) (ds : list Z),
  regs_preserved R0 R' -> cm M' -> world M' ->
  (forall a m, sp1 <= a -> a + m <= 2 ^ 64 -> (a + m <= oa + 24 \/ oa + 48 <= a) -> L5C.agree_on M1 M' a m) ->
  (forall B m, In (B, m) (PQM.lvec_own bX kX ++ PM.vs_own kbx ++ LBX) -> L5C.agree_on M1 M' B m) -> (forall e, PQST.err_ok RSEGS AD AQ M1 e -> PQST.err_ok RSEGS AD AQ M' e) ->
  adaptor_at M' oa ov (stK kx' kgx') -> kcontent M' (oa + 24) kx' (bs0 ++ ds) -> NEM.ascii ds -> PQM.ks_ok PQM.SMK kx' kgx' -> PM.vs_size kx' = PM.vs_size kx + PQV.ndig v ->
  PMSP.credit_keep cr1 cr' (PQM.pot_adaptor L (stK kx kgx)) (PQM.pot_adaptor L (stK kx' kgx')) ->
  model_but_vm model1 model' -> hi_heap HI (PQM.aown (stK kx' kgx') ++ LBX) cr' M' (m_vmmaps model') ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' ra M' model') K.

Definition saves (M : word -> option byte) : Prop :=
  L5.u64_at RSEGS M (sp1 - 8) (bv_unsigned (getr R0 (reg 1))) /\ L5.u64_at RSEGS M (sp1 - 16) (bv_unsigned (getr R0 (reg 8)))
  /\ L5.u64_at RSEGS M (sp1 - 24) (bv_unsigned (getr R0 (reg 9))) /\ L5.u64_at RSEGS M (sp1 - 32) (bv_unsigned (getr R0 (reg 18)))
  /\ L5.u64_at RSEGS M (sp1 - 40) (bv_unsigned (getr R0 (reg 19))).
Definition kept (R : bvmap 5 word) : Prop := forall x, In x [3; 4; 20; 21; 22; 23; 24; 25; 26; 27]%nat -> getr R (reg x) = getr R0 (reg x).
Definition AG (M : word -> option byte) : Prop := forall a m, sp1 <= a -> a + m <= 2 ^ 64 -> (a + m <= oa + 24 \/ oa + 48 <= a) -> L5C.agree_on M1 M a m.
(* [comment removed for export] *)
Definition DG (M : word -> option byte) (n : Z) : Prop := forall j, 0 <= j < n -> exists d, L5.u8_at RSEGS M (sp1 - 295 + j) d /\ 48 <= d <= 57.
