Lemma FIN (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (kx' : PM.vstr) (kgx' : Z) (cr : credit) (ds : list Z) :
  getr R (reg 1) = Z_to_bv 64 (bv_unsigned (getr R0 (reg 1))) -> getr R (reg 2) = Z_to_bv 64 sp1 ->
  getr R (reg 8) = Z_to_bv 64 (bv_unsigned (getr R0 (reg 8))) -> getr R (reg 9) = Z_to_bv 64 (bv_unsigned (getr R0 (reg 9))) ->
  getr R (reg 18) = Z_to_bv 64 (bv_unsigned (getr R0 (reg 18))) -> getr R (reg 19) = Z_to_bv 64 (bv_unsigned (getr R0 (reg 19))) -> kept R ->
  cm M -> world M -> AG M -> ABK M -> ERK M -> adaptor_at M oa ov (stK kx' kgx') -> kcontent M (oa + 24) kx' (bs0 ++ ds) -> NEM.ascii ds -> PQM.ks_ok PQM.SMK kx' kgx' -> PM.vs_size kx' = PM.vs_size kx + PQV.ndig v ->
  PMSP.credit_keep cr1 cr (PQM.pot_adaptor L (stK kx kgx)) (PQM.pot_adaptor L (stK kx' kgx')) -> model_but_vm model1 model ->
  hi_heap HI (PQM.aown (stK kx' kgx') ++ LBX) cr M (m_vmmaps model) ->
