  getr R (reg 2) = Z_to_bv 64 (sp1 - 320) -> getr R (reg 8) = Z_to_bv 64 (oa + 24) -> getr R (reg 9) = Z_to_bv 64 n ->
  getr R (reg 18) = Z_to_bv 64 (sp1 - 295) -> getr R (reg 19) = Z_to_bv 64 (sp1 - 295 + Z.of_nat j) -> kept R ->
