  PMSP.credit_keep cr1 cr (PQM.pot_adaptor L (stK kx kgx)) (PQM.pot_adaptor L (stK ky kgy)) -> model_but_vm model1 model ->
  hi_heap HI (PQM.aown (stK ky kgy) ++ LBX) cr M (m_vmmaps model) ->
